import React from 'react';
import Question from './Question';
import { ChevronDown, ChevronRight } from 'lucide-react';

function Category({ category, onVote, onToggle }) {
    const totalRating = category.questions.reduce((sum, q) => sum + q.rating, 0);

    return (
        <div className="category">
            <div className="category-header" onClick={onToggle}>
                <div className="arrow">
                    {category.isOpen
                        ? <ChevronDown size={24} strokeWidth={2} />
                        : <ChevronRight size={24} strokeWidth={2} />}
                </div>
                <h2 className="category-title">{category.name}</h2>
                <span className="total-rating">
                    {totalRating >= 0 ? `+${totalRating}` : totalRating}
                </span>
            </div>

            {category.isOpen && (
                <div className="questions">
                    {category.questions
                        .sort((a, b) => b.rating - a.rating)
                        .map(q => (
                            <Question
                                key={q.id}
                                question={q}
                                onVote={delta => onVote(category.id, q.id, delta)}
                            />
                        ))}
                </div>
            )}
        </div>
    );
}

export default Category;
